import itertools

def solve_small(n):
    min_max_sum = float('inf')
    for a in itertools.product([1, -1], repeat=n):
        max_sum = 0
        # We need to find all possible subsets S with gap condition
        # S = {t_1, ..., t_k} such that 1 <= t_1 < ... < t_k <= n and t_{i+1} - t_i <= 2
        # This can be solved with DP.
        # Let dp[i] be the set of possible sums ending at index i.
        # But we need all possible sums for *any* subset S that satisfies the gap condition.
        # Wait, the condition is only on the gap between consecutive elements of S.
        # The first element t_1 doesn't have a gap condition.
        # However, any subset S could be a valid one if we pick its elements.
        # Let's use DP to find the max absolute sum.

        # possible_sums[i] = set of all possible sums of a valid subset whose last element is i.
        possible_sums = [set() for _ in range(n)]
        for i in range(n):
            possible_sums[i].add(a[i])
            if i >= 1:
                for s in possible_sums[i-1]:
                    possible_sums[i].add(s + a[i])
            if i >= 2:
                for s in possible_sums[i-2]:
                    possible_sums[i].add(s + a[i])

        current_max_sum = 0
        for i in range(n):
            for s in possible_sums[i]:
                current_max_sum = max(current_max_sum, abs(s))

        max_sum = current_max_sum
        min_max_sum = min(min_max_sum, max_sum)

    return min_max_sum

for n in range(1, 16):
    print(f"n={n}, C={solve_small(n)}")

