import itertools

def solve_small_with_b(n):
    # b is a sequence of 0 or 2.
    # a is a sequence of 1 or -1.
    # We want to find max_b min_a max_{k, t_i} |sum_{i=1}^k (a_{t_i} + b_{t_i})|

    # To optimize, let c_i = a_i + b_i.
    # Since a_i in {1, -1} and b_i in {0, 2},
    # if b_i = 0, c_i is in {1, -1}.
    # if b_i = 2, c_i is in {3, 1}.

    max_min_max_sum = -1

    # Iterate over all possible b sequences (represented by which indices have b_i = 2)
    for b_indices in itertools.product([0, 2], repeat=n):
        # b_indices is our b sequence
        min_max_sum = float('inf')
        for a in itertools.product([1, -1], repeat=n):
            # c_i = a_i + b_i
            c = [a[i] + b_indices[i] for i in range(n)]

            # Now find max_S |sum_{i in S} c_i| with gap condition
            possible_sums = [set() for _ in range(n)]
            for i in range(n):
                possible_sums[i].add(c[i])
                if i >= 1:
                    for s in possible_sums[i-1]:
                        possible_sums[i].add(s + c[i])
                if i >= 2:
                    for s in possible_sums[i-2]:
                        possible_sums[i].add(s + c[i])

            current_max_sum = 0
            for i in range(n):
                for s in possible_sums[i]:
                    current_max_sum = max(current_max_sum, abs(s))

            min_max_sum = min(min_max_sum, current_max_sum)

        if min_max_sum > max_min_max_sum:
            max_min_max_sum = min_max_sum

    return max_min_max_sum

